test('Offline actual Confirm persists before navigation and IME note waits composition with immediate blur queue',async({page,context})=>{
 await offlineWorkerFixture(page);const calls:string[]=[];await page.route('**/api/**',r=>{calls.push(r.request().method());return r.fulfill({json:new URL(r.request().url()).pathname.startsWith('/api/operations/')?{kind:'unresolved'}:r.request().method()==='POST'?{kind:'recorded',originalOutcome:{status:'applied'}}:{item:{id:'synthetic',version:'a'.repeat(64),note:'Original',name:'Synthetic'}}})});
 await page.evaluate(async()=>{await(window as any).__realNoteRepository.authorize();(window as any).selectBackCase('queue-confirm')});await context.setOffline(true);await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect(page.locator('main')).toContainText('Saved on this device');const pending=await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'));expect(pending).toHaveLength(1);expect(calls).toEqual([]);await page.locator('.topbar button').click();expect(await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'))).toHaveLength(1);
 await context.setOffline(false);await page.evaluate(async()=>{await(window as any).__syncRealNote('07eae274-c4e9-44e9-bff4-900c3bf37c9b');(window as any).selectBackCase('note-real-storage')});const note=page.getByRole('textbox',{name:'Borrower note',exact:true});await expect(note).toHaveValue('Original');await context.setOffline(true);await note.dispatchEvent('compositionstart');await note.fill('IME ไทย');await page.waitForTimeout(800);expect(await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'))).toEqual([]);await note.dispatchEvent('compositionend');await expect.poll(()=>page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending')).length)).toBe(1);await note.fill('Blur latest');await page.getByRole('button',{name:'Parent rerender',exact:true}).click();await expect.poll(()=>page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending'))[0]?.value.command.inputs.note),{timeout:500}).toBe('Blur latest');expect(calls.filter(x=>x==='POST')).toHaveLength(1);
});

for(const conflict of [false,true])test('Offline latest note survives leaving during predecessor transport '+(conflict?'and retains later owner conflict':'and binds verified current version'),async({page})=>{
 let release!:()=>void;const held=new Promise<void>(resolve=>release=resolve);let applied=false;const posts:any[]=[];const item:any={id:'synthetic',version:'a'.repeat(64),note:'Original',name:'Synthetic',description:null,communicationName:null,instagramUsername:null,city:null,workingLocation:null,address:null,hidden:false,referrerId:null,preferredReceivingAccountId:null};
 await offlineWorkerFixture(page);await page.route('**/api/**',async r=>{const path=new URL(r.request().url()).pathname;if(r.request().method()==='POST'){const command=r.request().postDataJSON();posts.push(command);if(posts.length===1){await held;applied=true;Object.assign(item,{...command.inputs,version:'b'.repeat(64)});if(conflict)item.note='Later owner write'}return r.fulfill({json:{kind:'recorded',originalOutcome:{status:'applied'}}})}if(path==='/api/borrower-options')return r.fulfill({json:{accounts:[],referrers:[]}});if(path.startsWith('/api/operations/'))return r.fulfill({json:applied&&path.endsWith(posts[0]?.requestId)?{kind:'recorded',originalOutcome:{status:'applied'}}:{kind:'unresolved'}});return r.fulfill({json:{item}})});
 await page.evaluate(async()=>{await(window as any).__realNoteRepository.authorize();(window as any).selectBackCase('note-real-storage')});const note=page.getByRole('textbox',{name:'Borrower note',exact:true});await expect(note).toHaveValue('Original');await note.fill('First dispatched note');await expect.poll(()=>posts.length).toBe(1);await note.fill('Latest durable note');await expect.poll(()=>page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending')).length)).toBe(2);const latest=await page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending')).find((r:any)=>r.value.command.inputs.note==='Latest durable note'));expect(latest.value.notePredecessor.requestId).toBe(posts[0].requestId);const latestId=latest.value.command.requestId;
 await page.evaluate(()=>(window as any).selectBackCase(null));release();await expect.poll(()=>page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending')).length)).toBe(1);await page.evaluate(async(id)=>{await(window as any).__syncRealNote(id)},latestId);
 if(conflict){expect(posts).toHaveLength(1);const row=await page.evaluate(id=>(window as any).__realNoteRepository.pending(id),latestId);expect(row.sync.state).toBe('blocked');expect(row.sync.code).toBe('source_conflict');expect(row.value.command.inputs.note).toBe('Latest durable note');await page.evaluate(()=>(window as any).selectBackCase('queue-list'));await page.getByRole('button',{name:'Review saved change',exact:true}).click();page.once('dialog',dialog=>dialog.accept());await page.getByRole('button',{name:'Remove saved change',exact:true}).click();await expect(page.getByText('No unsynced changes.',{exact:true})).toBeVisible();expect(await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'))).toEqual([]);}else{expect(posts).toHaveLength(2);expect(posts[1].requestId).toBe(latestId);expect(posts[1].expectedVersion).toBe('b'.repeat(64));expect(posts[1].inputs.note).toBe('Latest durable note');expect(await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'))).toEqual([])}
});

test('Offline unfinished loan draft restores only original borrower form and never syncs before Save',async({page})=>{
 await offlineWorkerFixture(page);let posts=0;await page.route('**/api/**',r=>{if(r.request().method()==='POST')posts++;return r.fulfill({json:{accounts:[]}})});await page.evaluate(async()=>{const repo=(window as any).__realNoteRepository;await repo.authorize();await repo.saveDraft('loan:legacy-new',{domain:'loan',label:'Original borrower',draft:{id:'legacy-new',source:null,fields:{borrowerId:'borrower-A',principal:'123.45',arrangement:'Preserved unfinished loan',loanDate:null,transferFee:null,disbursingAccountId:null,type:null,dueDate:null,dailyPayment:null,fixedInterest:null,currentDailyInterest:null,paymentInterval:1,autoChargeEnabled:true,scheduleAnchor:null},accounts:[]}});(window as any).selectBackCase('loan-real-B')});await expect(page.getByRole('spinbutton',{name:'Principal Amount',exact:false})).toHaveValue('');await page.evaluate(()=>(window as any).selectBackCase(null));await page.evaluate(()=>(window as any).selectBackCase('loan-real-A'));await expect(page.getByRole('spinbutton',{name:'Principal Amount',exact:false})).toHaveValue('123.45');await expect(page.getByRole('textbox',{name:'Loan Arrangement',exact:true})).toHaveValue('Preserved unfinished loan');await page.evaluate(async()=>{await(window as any).__offlineTest.syncSavedRequests({...((window as any).__syncAccess),offline:(window as any).__realNoteRepository});(window as any).selectBackCase('queue-list')});await expect(page.getByText('No unsynced changes.',{exact:true})).toBeVisible();expect(posts).toBe(0);expect((await page.evaluate(()=>(window as any).__realNoteRepository.list('draft')))[0].key).toBe('draft:loan:legacy-new');
});

test('Offline existing borrower draft restores edits without current read overwriting them',async({page})=>{
 await offlineWorkerFixture(page);const requests:string[]=[];await page.route('**/api/**',r=>{requests.push(new URL(r.request().url()).pathname);return r.fulfill({json:{accounts:[],referrers:[],item:{id:'synthetic',name:'Server overwrite',version:'b'.repeat(64)}}})});await page.evaluate(async()=>{const fields={name:'Preserved local borrower',description:null,communicationName:null,instagramUsername:null,city:null,workingLocation:null,address:null,hidden:false,referrerId:null,preferredReceivingAccountId:null,note:null};const repo=(window as any).__realNoteRepository;await repo.authorize();await repo.saveDraft('borrower:synthetic',{domain:'borrower',label:'Existing borrower',draft:{id:'synthetic',record:{id:'synthetic',version:'a'.repeat(64),...fields},fields,accounts:[],referrers:[]}});(window as any).selectBackCase('borrower-real-edit')});await expect(page.getByRole('textbox',{name:'Borrower Name - Thai',exact:true})).toHaveValue('Preserved local borrower');expect(requests).not.toContain('/api/borrower-records/synthetic');expect(await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'))).toEqual([]);
});

test('Waiting to sync badge counts authorized pending states and stays legible in expanded and compact menus',async({page},info)=>{
 await page.setViewportSize({width:390,height:844});await offlineWorkerFixture(page);await page.evaluate(async()=>{const repo=(window as any).__realNoteRepository;await repo.authorize();await repo.saveDraft('hidden-draft',{domain:'loan',draft:{principal:'1'}});await repo.saveSnapshot('hidden-snapshot',{charges:[]});(window as any).selectBackCase('queue-badge')});const buttons=page.locator('.waiting-sync-button');await expect(buttons).toHaveCount(2);await expect(page.locator('.waiting-sync-badge')).toHaveCount(0);await expect(buttons.first()).toHaveAttribute('aria-label','Waiting to sync');
 const ids=await page.evaluate(async()=>{const repo=(window as any).__realNoteRepository,ids=[crypto.randomUUID(),crypto.randomUUID(),crypto.randomUUID()];for(const id of ids)await repo.savePending(id,{domain:'borrower',command:{requestId:id,operation:'borrower.update',targetId:'synthetic',inputs:{note:id}}});await repo.claimPending(ids[1],'badge-sync');await repo.claimPending(ids[2],'badge-block');await repo.settlePending(ids[2],'badge-block',{state:'blocked',attempted:false});return ids});await expect(page.locator('.waiting-sync-badge')).toHaveText(['3','3']);await expect(buttons.first()).toHaveAttribute('aria-label','Waiting to sync, 3 saved changes');await expect(buttons.last()).toHaveAttribute('aria-label','รอซิงค์ มีรายการที่บันทึก 3 รายการ');
 for(const button of await buttons.all()){const b=await button.boundingBox(),badge=await button.locator('.waiting-sync-badge').boundingBox();expect(badge!.x+badge!.width).toBeGreaterThan(b!.x+b!.width-1);expect(badge!.y).toBeLessThan(b!.y);expect(badge!.width).toBeGreaterThanOrEqual(20);await expect(button.locator('.waiting-sync-badge')).toHaveAttribute('aria-hidden','true')}expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('waiting-sync-badge-390.png')});
 await page.evaluate(async id=>{await(window as any).__realNoteRepository.remove('pending',id)},ids[0]);await expect(page.locator('.waiting-sync-badge')).toHaveText(['2','2']);await page.evaluate(async()=>{const other=(window as any).__offlineTest.ownerOfflineRepository({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'badge-other'},'synthetic');await other.authorize();(window as any).__badgeRepository=other;(window as any).selectBackCase(null)});await page.evaluate(()=>(window as any).selectBackCase('queue-badge'));await expect(page.locator('.waiting-sync-badge')).toHaveCount(0);
 await page.evaluate(()=>{delete(window as any).__badgeRepository;(window as any).selectBackCase(null)});await page.evaluate(()=>(window as any).selectBackCase('queue-badge'));await expect(page.locator('.waiting-sync-badge')).toHaveText(['2','2']);await page.evaluate(async()=>{const repo=(window as any).__realNoteRepository;await new Promise<void>((resolve,reject)=>{const request=indexedDB.open(repo.scopeName,1);request.onsuccess=()=>{const db=request.result,tx=db.transaction('records','readwrite');tx.objectStore('records').put({key:'lease:owner',kind:'lease',savedAt:Date.now(),value:{verifiedAt:Date.now()-25*60*60*1000}});tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(Error('Fixture expiration failed'))}});window.dispatchEvent(new Event('focus'))});await expect(page.locator('.waiting-sync-badge')).toHaveCount(0);
 await page.evaluate(async()=>{await(window as any).__realNoteRepository.authorize();window.dispatchEvent(new Event('focus'))});await expect(page.locator('.waiting-sync-badge')).toHaveText(['2','2']);await page.evaluate(async ids=>{for(const id of ids.slice(1))await(window as any).__realNoteRepository.remove('pending',id)},ids);await expect(page.locator('.waiting-sync-badge')).toHaveCount(0);expect((await page.evaluate(()=>(window as any).__realNoteRepository.list('draft'))).length).toBe(1);
});

test('Offline actual receiver confirms cached allocations and persists selected receipt for reconnect upload',async({page,context})=>{
 await offlineWorkerFixture(page);const events:string[]=[];const draft={businessDate:'2026-10-14',borrower:{id:'borrower',displayName:'Synthetic receipt borrower'},charges:[{id:'charge',chargeDate:'2026-10-14',loanDisplayKey:'Synthetic loan',amountRemaining:'25',principalRemaining:'20',interestRemaining:'5'}],accounts:[{id:'account',label:'Synthetic account'}]};await page.route('**/api/**',r=>{const path=new URL(r.request().url()).pathname;events.push(r.request().method()+' '+path);return r.fulfill({json:path.startsWith('/api/payment-drafts/')?draft:path.includes('/receipts/')?{ok:true}:r.request().method()==='POST'?{kind:'recorded',originalOutcome:{status:'posted'}}:{kind:'unresolved'}})});
 await page.evaluate(async()=>{await(window as any).__realNoteRepository.authorize();(window as any).selectBackCase('receiving-real')});await page.getByRole('combobox',{name:/^Receiving account/}).selectOption('account');await page.getByRole('textbox',{name:/^Amount received(?: \*)?$/}).fill('25');await page.getByRole('checkbox',{name:/Allocate to Synthetic loan/}).check();await context.setOffline(true);const png=await(await import('sharp')).default({create:{width:20,height:30,channels:3,background:'#e58a32'}}).png().toBuffer();await page.locator('input[type=file]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:png});await page.getByRole('button',{name:'Review payment',exact:true}).click();await page.getByRole('button',{name:'Confirm payment',exact:true}).click();await expect(page.locator('main')).toContainText('Saved on this device');const rows=await page.evaluate(()=>(window as any).__realNoteRepository.list('pending'));expect(rows).toHaveLength(1);expect(rows[0].value.command.amountReceived).toBe('25');expect(rows[0].value.receipt.id).toBe(rows[0].value.command.receiptId);expect(await page.evaluate(async()=>(await(window as any).__realNoteRepository.list('pending'))[0].value.receipt.image.size)).toBe(png.length);expect(events.filter(e=>e.startsWith('POST'))).toEqual([]);
 await page.evaluate(()=>(window as any).selectBackCase('queue-list'));await context.setOffline(false);await page.evaluate(id=>(window as any).__syncRealNote(id),rows[0].value.command.requestId);await expect(page.getByText('No unsynced changes.',{exact:true})).toBeVisible();const final=events.slice(-3);expect(final[0]).toBe('GET /api/payment-commands/'+rows[0].value.command.requestId);expect(final[1]).toBe('POST /api/payment-commands/'+rows[0].value.command.requestId+'/receipts/'+rows[0].value.receipt.id);expect(final[2]).toBe('POST /api/payment-commands');
});
